(function(root){'use strict';
const encode=s=>new TextEncoder().encode(String(s)),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const crcTable=Array.from({length:256},(_,n)=>{for(let k=0;k<8;k++)n=n&1?0xedb88320^(n>>>1):n>>>1;return n>>>0});
function crc(bytes){let n=0xffffffff;for(const b of bytes)n=crcTable[(n^b)&255]^(n>>>8);return(n^0xffffffff)>>>0;}
function zip(files){const local=[],central=[];let pos=0;for(const f of files){if(!/^[\w\-/\.]+$/.test(f.name)||f.name.includes('..'))throw Error('자료 파일명 오류');const name=encode(f.name),data=typeof f.content==='string'?encode(f.content):f.content,sum=crc(data),l=new Uint8Array(30+name.length),v=new DataView(l.buffer);v.setUint32(0,0x04034b50,true);v.setUint16(4,20,true);v.setUint16(6,0x800,true);v.setUint16(12,0x21,true);v.setUint32(14,sum,true);v.setUint32(18,data.length,true);v.setUint32(22,data.length,true);v.setUint16(26,name.length,true);l.set(name,30);local.push(l,data);const c=new Uint8Array(46+name.length),cv=new DataView(c.buffer);cv.setUint32(0,0x02014b50,true);cv.setUint16(4,20,true);cv.setUint16(6,20,true);cv.setUint16(8,0x800,true);cv.setUint16(14,0x21,true);cv.setUint32(16,sum,true);cv.setUint32(20,data.length,true);cv.setUint32(24,data.length,true);cv.setUint16(28,name.length,true);cv.setUint32(42,pos,true);c.set(name,46);central.push(c);pos+=l.length+data.length;}const length=central.reduce((n,c)=>n+c.length,0),end=new Uint8Array(22),ev=new DataView(end.buffer);ev.setUint32(0,0x06054b50,true);ev.setUint16(8,files.length,true);ev.setUint16(10,files.length,true);ev.setUint32(12,length,true);ev.setUint32(16,pos,true);const result=new Uint8Array(pos+length+22);let at=0;for(const part of [...local,...central,end]){result.set(part,at);at+=part.length;}return result;}
function page(title,content){content=String(content).replace(/<details(?![^>]*\bopen\b)(?=[\s>])/g,'<details open');return '<!doctype html><html lang="ko"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta http-equiv="Content-Security-Policy" content="default-src \'none\'; style-src \'unsafe-inline\'; img-src data:; object-src \'none\'; base-uri \'none\'"><title>'+esc(title)+'</title><style>body{font:18px/1.85 sans-serif;color:#243f54;max-width:1100px;margin:35px auto;padding:0 20px}table{border-collapse:collapse;width:100%;font-size:16px}td,th{border:1px solid #cbd7e0;padding:10px;text-align:left;vertical-align:top}h2{font-size:26px}h3{font-size:22px}h4,dt{font-size:19px;font-weight:700}dd{margin:4px 0 18px}section{margin:22px 0}details{margin:15px 0}svg{width:100%;height:auto}pre{white-space:pre-wrap;font:inherit}input,button{display:none}@media print{body{margin:0}.execution-task{break-inside:avoid}}</style></head><body><h1>'+esc(title)+'</h1>'+content+'<footer>OY-RALS · 김지훈 · 담당자 검토 전 초안</footer></body></html>';}
const csv=rows=>'\uFEFF'+rows.map(row=>row.map(value=>{let s=String(value??'');if(/^[=+@-]/.test(s))s="'"+s;return '"'+s.replace(/"/g,'""')+'"'}).join(',')).join('\r\n');
const loaders=new Map();async function modules(){for(const name of ['resource-links.js','insights.js','evidence-matrix.js','professional-response.js','role-actions.js','casework-knowledge-v7.js','casework-v7.js','case-synthesis-v71.js','case-action-model.js','case-documents.js','case-form-model.js']){if(!loaders.has(name))loaders.set(name,new Promise((resolve,reject)=>{const script=document.createElement('script');script.src=name+'?v=20261024-synthesis71';script.onload=resolve;script.onerror=()=>{loaders.delete(name);reject(Error('출력 모듈을 읽지 못했습니다: '+name))};document.head.append(script)}));await loaders.get(name);}}
function files(p,options={}){const include=!!options.includeContext,safe={...p,caseContext:include?p.caseContext:''},x=root.YouthSynthesis.build(safe),backup={format:'osan-youth-risk-backup-v1',answers:p.answers.slice(),explicit:p.explicit.slice(),followups:{...p.followups}},questions=p.domains.flatMap(g=>g.items);const out=[{name:'README.txt',content:'OY-RALS 전체 자료\n01-summary.html을 브라우저로 열어 확인·인쇄/PDF 저장할 수 있습니다.\nassessment.json은 기존 비식별 평가 복원용이며 서술은 포함하지 않습니다.\n'+(include?'선택 사례정보와 현재 작성 기록을 포함하도록 선택한 파일입니다. 민감정보·기관 보관기준을 확인하세요.':'선택 사례정보·직접 기록은 제외했습니다. 포함하려면 다운로드 옵션을 선택하세요.')+'\n모든 내용은 검토 초안입니다. 실제 합의·기관 접수·개입 효과를 자동 확정하지 않습니다.'},
 {name:'assessment.json',content:JSON.stringify(backup,null,2)},
 {name:'01-summary.html',content:page('종합 사정·영역별 응답',root.YouthSynthesis.html(safe)+root.YouthSynthesis.graph(safe))},
 {name:'02-review.txt',content:root.YouthSynthesis.text(safe,include)},
 {name:'03-service-plan.html',content:page('서비스계획서 · 협의안',root.YouthCaseDocuments.render(safe,'teacher','plan'))},
 {name:'04-case-conference.html',content:page('사례협의안 · 회의 전',root.YouthCaseDocuments.render(safe,'teacher','assessment'))},
 {name:'05-responses.csv',content:csv([['문항','평가 내용','응답'],...p.answers.map((v,i)=>[i+1,questions[i],v==='unknown'?'미상':v])])},
 {name:'06-resources.csv',content:csv([['기관 후보','서비스','주소','전화','접수 상태'],...root.YouthMap.referrals(p).map(g=>[g.name,g.services.map(r=>r['서비스명']).join(' · '),g.primary.address||'미확인',g.primary['대표전화']||'미확인','문의 전·대상/관할/접수 확인 필요'])])}];
 out.push({name:'09-domain-chart.svg',content:root.YouthSynthesis.graph(safe).match(/<svg[\s\S]*?<\/svg>/)[0]},{name:'10-domain-summary.csv',content:csv([['영역','확인 문항','미상 문항','확인 합계','영역 전체 최대점','평균(미상 시 보류)'],...x.areas.map(g=>[g.name,g.known.length,g.unknown.length,g.sum,g.ids.length*4,g.mean===null?'보류':g.mean.toFixed(2)])])});
 const form=root.YouthCaseForms.build(safe);out.push({name:'07-intake.txt',content:root.YouthCaseForms.text(form,'intake')},{name:'08-needs-assessment.txt',content:root.YouthCaseForms.text(form,'needs')});
 if(include&&root.YouthSynthesis.note(p).present)out.push({name:'case-context.txt',content:String(typeof p.caseContext==='string'?p.caseContext:p.caseContext?.text||'')});
 if(include)for(const [i,record] of (options.records||[]).entries()){const prefix='records/revision-'+record.revision+'-draft-'+(i+1)+'/';out.push({name:prefix+'written-record.html',content:page('작성한 실행·회의·점검 기록',record.html||'<p>작성 자료 없음</p>')},{name:prefix+'written-fields.json',content:JSON.stringify(record.fields,null,2)});if(record.assessment)out.push({name:prefix+'source-assessment.json',content:JSON.stringify(record.assessment,null,2)});if(record.forms)out.push({name:prefix+'intake.txt',content:root.YouthCaseForms.text(record.forms,'intake')},{name:prefix+'needs.txt',content:root.YouthCaseForms.text(record.forms,'needs')});}
 if(x.decision.incomplete)out[0].content+='\n미상 '+x.decision.unknownItems.length+'문항: 전체 점수·위기수준 보류. 미상을 0점으로 처리하지 않습니다.';return out;}
async function download(p,options={}){await modules();const content=files(p,options),blob=new Blob([zip(content)],{type:'application/zip'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='OY-RALS-all-materials-'+new Date().toLocaleDateString('sv-SE',{timeZone:'Asia/Seoul'})+'.zip';a.click();setTimeout(()=>URL.revokeObjectURL(url),3000);return content.map(f=>f.name);}
const api={zip,crc,page,csv,files,download};if(typeof module!=='undefined'&&module.exports)module.exports=api;else root.YouthBundle=api;
})(typeof window!=='undefined'?window:globalThis);
